SELECT /* selectMasterMpStHeadTeamResultList */ YYYY , TEAM_CD , TEAM_NM , ORDER_NUM , GUBUN1 , GUBUN2 , JAN , FEB , MAR , APR , MAY , JUN , JUL , AUG , SEP , OCT , NOV , DEC , TOTAL FROM V_BNTTEAM_SUM WHERE 1 = 1
AND YYYY=#{st_year}
AND DIVISION_CD = #{st_user_division}
AND TEAM_CD IN (#{st_user_division}, #{st_user_dept})
AND TEAM_CD IN ('*', #{st_user_dept})
AND TEAM_CD IN ('*', '012', '119', '106')

SELECT /* selectMasterMpStHeadTeamResultList1 */ SUM(X.LAST_YEAR01) AS LAST_YEAR01, SUM(X.THIS_YEAR01) AS THIS_YEAR01, SUM(X.LAST_YEAR02) AS LAST_YEAR02, SUM(X.THIS_YEAR02) AS THIS_YEAR02, SUM(X.LAST_YEAR03) AS LAST_YEAR03, SUM(X.THIS_YEAR03) AS THIS_YEAR03, SUM(X.LAST_YEAR04) AS LAST_YEAR04, SUM(X.THIS_YEAR04) AS THIS_YEAR04, SUM(X.LAST_YEAR05) AS LAST_YEAR05, SUM(X.THIS_YEAR05) AS THIS_YEAR05, SUM(X.LAST_YEAR06) AS LAST_YEAR06, SUM(X.THIS_YEAR06) AS THIS_YEAR06, SUM(X.LAST_YEAR07) AS LAST_YEAR07, SUM(X.THIS_YEAR07) AS THIS_YEAR07, SUM(X.LAST_YEAR08) AS LAST_YEAR08, SUM(X.THIS_YEAR08) AS THIS_YEAR08, SUM(X.LAST_YEAR09) AS LAST_YEAR09, SUM(X.THIS_YEAR09) AS THIS_YEAR09, SUM(X.LAST_YEAR10) AS LAST_YEAR10, SUM(X.THIS_YEAR10) AS THIS_YEAR10, SUM(X.LAST_YEAR11) AS LAST_YEAR11, SUM(X.THIS_YEAR11) AS THIS_YEAR11, SUM(X.LAST_YEAR12) AS LAST_YEAR12, SUM(X.THIS_YEAR12) AS THIS_YEAR12 FROM ( SELECT DECODE(YYYY, #{st_last_year}, JAN, 0) AS LAST_YEAR01, DECODE(YYYY, #{st_year}, JAN, 0) AS THIS_YEAR01, DECODE(YYYY, #{st_last_year}, FEB, 0) AS LAST_YEAR02, DECODE(YYYY, #{st_year}, FEB, 0) AS THIS_YEAR02, DECODE(YYYY, #{st_last_year}, MAR, 0) AS LAST_YEAR03, DECODE(YYYY, #{st_year}, MAR, 0) AS THIS_YEAR03, DECODE(YYYY, #{st_last_year}, APR, 0) AS LAST_YEAR04, DECODE(YYYY, #{st_year}, APR, 0) AS THIS_YEAR04, DECODE(YYYY, #{st_last_year}, MAY, 0) AS LAST_YEAR05, DECODE(YYYY, #{st_year}, MAY, 0) AS THIS_YEAR05, DECODE(YYYY, #{st_last_year}, JUN, 0) AS LAST_YEAR06, DECODE(YYYY, #{st_year}, JUN, 0) AS THIS_YEAR06, DECODE(YYYY, #{st_last_year}, JUL, 0) AS LAST_YEAR07, DECODE(YYYY, #{st_year}, JUL, 0) AS THIS_YEAR07, DECODE(YYYY, #{st_last_year}, AUG, 0) AS LAST_YEAR08, DECODE(YYYY, #{st_year}, AUG, 0) AS THIS_YEAR08, DECODE(YYYY, #{st_last_year}, SEP, 0) AS LAST_YEAR09, DECODE(YYYY, #{st_year}, SEP, 0) AS THIS_YEAR09, DECODE(YYYY, #{st_last_year}, OCT, 0) AS LAST_YEAR10, DECODE(YYYY, #{st_year}, OCT, 0) AS THIS_YEAR10, DECODE(YYYY, #{st_last_year}, NOV, 0) AS LAST_YEAR11, DECODE(YYYY, #{st_year}, NOV, 0) AS THIS_YEAR11, DECODE(YYYY, #{st_last_year}, DEC, 0) AS LAST_YEAR12, DECODE(YYYY, #{st_year}, DEC, 0) AS THIS_YEAR12 FROM V_BNTTEAM_SUM WHERE 1=1 AND GUBUN = 'C'
AND YYYY IN (#{st_last_year}, #{st_year})
AND TEAM_CD = #{st_user_dept}
AND TEAM_CD = '*'
) X
